8	 *   def main():
9	 *       parser = argparse.ArgumentParser()
10	 *       parser.add_argument('--key', type=str, required=True)   # 16 bytes key
11	 *       parser.add_argument('--data', type=str, required=True)  # 16 bytes data
12	 *       args = parser.parse_args()
13	 *
14	 *       # Test round-trip encryption/decryption with ECB
15	 *       aes = pyaes.AESModeOfOperationECB(args.key.encode())
16	 *       ciphertext = aes.encrypt(args.data.encode())
17	 *       plaintext = aes.decrypt(ciphertext)
18	 *       print(ciphertext)
19	 *       print(plaintext)
20	 *
21	 * Usage: node test13.mjs --key KEY --data DATA
22	 */
