1	/**
2	 * The AES block cipher itself: one 16-byte block in, one 16-byte block out.
3	 *
4	 * The state is held as a flat 16-byte array in AES column-major order, i.e.
5	 * `state[4 * column + row]`, which is also the order bytes arrive in.
6	 */
7	
8	import { ValueError } from '../python/exceptions.mjs';
9	import { expandKey, roundCount, BLOCK_SIZE, VALID_KEY_SIZES } from './keyExpansion.mjs';
10	import {
11	  INV_SBOX,
12	  MUL11,
13	  MUL13,
14	  MUL14,
15	  MUL2,
16	  MUL3,
17	  MUL9,
18	  SBOX,
19	} from './tables.mjs';
20	
21	/**
22	 * XOR one round key into the state.
23	 *
24	 * @param {Uint8Array} state
25	 * @param {Uint32Array} schedule
26	 * @param {number} round
27	 */
28	function addRoundKey(state, schedule, round) {
29	  for (let column = 0; column < 4; column += 1) {
30	    const word = schedule[round * 4 + column];
31	    const o = column * 4;
32	    state[o] ^= (word >>> 24) & 0xff;
33	    state[o + 1] ^= (word >>> 16) & 0xff;
34	    state[o + 2] ^= (word >>> 8) & 0xff;
35	    state[o + 3] ^= word & 0xff;
36	  }
37	}
38	
39	/**
40	 * Apply a byte substitution table to the whole state.
41	 *
42	 * @param {Uint8Array} state
43	 * @param {Uint8Array} table
44	 */
45	function substituteBytes(state, table) {
46	  for (let i = 0; i < BLOCK_SIZE; i += 1) state[i] = table[state[i]];
47	}
48	
49	/**
50	 * ShiftRows: row r rotates left by r columns.
51	 *
52	 * @param {Uint8Array} state
53	 */
54	function shiftRows(state) {
55	  const source = state.slice();
56	  for (let row = 1; row < 4; row += 1) {
57	    for (let column = 0; column < 4; column += 1) {
58	      state[column * 4 + row] = source[(((column + row) % 4) * 4) + row];
59	    }
60	  }
61	}
62	
63	/**
64	 * InvShiftRows: row r rotates right by r columns.
65	 *
66	 * @param {Uint8Array} state
67	 */
68	function invShiftRows(state) {
69	  const source = state.slice();
70	  for (let row = 1; row < 4; row += 1) {
71	    for (let column = 0; column < 4; column += 1) {
72	      state[column * 4 + row] = source[(((column - row + 4) % 4) * 4) + row];
73	    }
74	  }
75	}
76	
77	/**
78	 * MixColumns: multiply each column by the fixed polynomial {03}x^3 + {01}x^2 +
79	 * {01}x + {02}.
80	 *
81	 * @param {Uint8Array} state
82	 */
83	function mixColumns(state) {
84	  for (let column = 0; column < 4; column += 1) {
85	    const o = column * 4;
86	    const a0 = state[o];
87	    const a1 = state[o + 1];
88	    const a2 = state[o + 2];
89	    const a3 = state[o + 3];
90	    state[o] = MUL2[a0] ^ MUL3[a1] ^ a2 ^ a3;
91	    state[o + 1] = a0 ^ MUL2[a1] ^ MUL3[a2] ^ a3;
92	    state[o + 2] = a0 ^ a1 ^ MUL2[a2] ^ MUL3[a3];
93	    state[o + 3] = MUL3[a0] ^ a1 ^ a2 ^ MUL2[a3];
94	  }
95	}
96	
97	/**
98	 * InvMixColumns: multiply each column by the inverse polynomial
99	 * {0b}x^3 + {0d}x^2 + {09}x + {0e}.
100	 *
101	 * @param {Uint8Array} state
102	 */
103	function invMixColumns(state) {
104	  for (let column = 0; column < 4; column += 1) {
105	    const o = column * 4;
106	    const a0 = state[o];
107	    const a1 = state[o + 1];
108	    const a2 = state[o + 2];
109	    const a3 = state[o + 3];
110	    state[o] = MUL14[a0] ^ MUL11[a1] ^ MUL13[a2] ^ MUL9[a3];
111	    state[o + 1] = MUL9[a0] ^ MUL14[a1] ^ MUL11[a2] ^ MUL13[a3];
112	    state[o + 2] = MUL13[a0] ^ MUL9[a1] ^ MUL14[a2] ^ MUL11[a3];
113	    state[o + 3] = MUL11[a0] ^ MUL13[a1] ^ MUL9[a2] ^ MUL14[a3];
114	  }
115	}
116	
117	/**
118	 * A raw AES block cipher, mirroring `pyaes.AES`.
119	 *
120	 * The single-block API and the `Invalid key size` error text are what the
121	 * Python program observes through `pyaes.AESModeOfOperationECB`.
122	 */
123	export class AES {
124	  /**
125	   * @param {Uint8Array} key 16, 24 or 32 bytes
126	   */
127	  constructor(key) {
128	    if (!VALID_KEY_SIZES.includes(key.length)) {
129	      throw new ValueError('Invalid key size');
130	    }
131	    this.key = Uint8Array.from(key);
132	    this.rounds = roundCount(key.length);
133	    this.schedule = expandKey(this.key);
134	  }
135	
136	  /**
137	   * Encrypt exactly one block.
138	   *
139	   * @param {Uint8Array} block 16 bytes
140	   * @returns {Uint8Array} 16 bytes
141	   */
142	  encrypt(block) {
143	    const state = Uint8Array.from(block);
144	    addRoundKey(state, this.schedule, 0);
145	    for (let round = 1; round < this.rounds; round += 1) {
146	      substituteBytes(state, SBOX);
147	      shiftRows(state);
148	      mixColumns(state);
149	      addRoundKey(state, this.schedule, round);
150	    }
151	    substituteBytes(state, SBOX);
152	    shiftRows(state);
153	    addRoundKey(state, this.schedule, this.rounds);
154	    return state;
155	  }
156	
157	  /**
158	   * Decrypt exactly one block.
159	   *
160	   * @param {Uint8Array} block 16 bytes
161	   * @returns {Uint8Array} 16 bytes
162	   */
163	  decrypt(block) {
164	    const state = Uint8Array.from(block);
165	    addRoundKey(state, this.schedule, this.rounds);
166	    for (let round = this.rounds - 1; round >= 1; round -= 1) {
167	      invShiftRows(state);
168	      substituteBytes(state, INV_SBOX);
169	      addRoundKey(state, this.schedule, round);
170	      invMixColumns(state);
171	    }
172	    invShiftRows(state);
173	    substituteBytes(state, INV_SBOX);
174	    addRoundKey(state, this.schedule, 0);
175	    return state;
176	  }
177	}
