1	/**
2	 * Rijndael key expansion for 128-, 192- and 256-bit keys.
3	 */
4	
5	import { RCON, SBOX } from './tables.mjs';
6	
7	/** AES operates on 4-byte words and a 16-byte block. */
8	export const WORD_SIZE = 4;
9	export const BLOCK_SIZE = 16;
10	
11	/** Key sizes accepted by AES, in bytes. */
12	export const VALID_KEY_SIZES = [16, 24, 32];
13	
14	/**
15	 * Substitute all four bytes of a word through the S-box.
16	 *
17	 * @param {number} word unsigned 32-bit
18	 * @returns {number} unsigned 32-bit
19	 */
20	function subWord(word) {
21	  return (
22	    ((SBOX[(word >>> 24) & 0xff] << 24) |
23	      (SBOX[(word >>> 16) & 0xff] << 16) |
24	      (SBOX[(word >>> 8) & 0xff] << 8) |
25	      SBOX[word & 0xff]) >>>
26	    0
27	  );
28	}
29	
30	/**
31	 * Rotate a word one byte to the left.
32	 *
33	 * @param {number} word unsigned 32-bit
34	 * @returns {number} unsigned 32-bit
35	 */
36	function rotWord(word) {
37	  return (((word << 8) | (word >>> 24)) & 0xffffffff) >>> 0;
38	}
39	
40	/**
41	 * Number of cipher rounds for a given key length in bytes.
42	 *
43	 * @param {number} keyLength
44	 * @returns {number}
45	 */
46	export function roundCount(keyLength) {
47	  return keyLength / WORD_SIZE + 6;
48	}
49	
50	/**
51	 * Expand a cipher key into the round-key word schedule.
52	 *
53	 * @param {Uint8Array} key 16, 24 or 32 bytes
54	 * @returns {Uint32Array} 4 * (rounds + 1) words, big-endian per word
55	 */
56	export function expandKey(key) {
57	  const nk = key.length / WORD_SIZE;
58	  const rounds = roundCount(key.length);
59	  const total = WORD_SIZE * (rounds + 1);
60	  const schedule = new Uint32Array(total);
61	
62	  for (let i = 0; i < nk; i += 1) {
63	    const o = i * WORD_SIZE;
64	    schedule[i] =
65	      ((key[o] << 24) | (key[o + 1] << 16) | (key[o + 2] << 8) | key[o + 3]) >>> 0;
66	  }
67	
68	  for (let i = nk; i < total; i += 1) {
69	    let temp = schedule[i - 1];
70	    if (i % nk === 0) {
71	      temp = (subWord(rotWord(temp)) ^ (RCON[i / nk] << 24)) >>> 0;
72	    } else if (nk > 6 && i % nk === 4) {
73	      temp = subWord(temp);
74	    }
75	    schedule[i] = (schedule[i - nk] ^ temp) >>> 0;
76	  }
77	
78	  return schedule;
79	}
