1	/**
2	 * Arithmetic in the Rijndael finite field GF(2^8).
3	 *
4	 * Every table below is *derived*, never transcribed: the field is generated
5	 * from the AES reduction polynomial x^8 + x^4 + x^3 + x + 1 (0x11b) so there
6	 * is no opportunity for a hand-typed constant to be wrong.
7	 */
8	
9	/** The AES reduction polynomial, without its x^8 term. */
10	const REDUCTION_POLY = 0x1b;
11	
12	/**
13	 * Multiply `a` by 2 in GF(2^8) (the classic "xtime" operation).
14	 *
15	 * @param {number} a byte
16	 * @returns {number} byte
17	 */
18	export function xtime(a) {
19	  const shifted = (a << 1) & 0xff;
20	  return a & 0x80 ? shifted ^ REDUCTION_POLY : shifted;
21	}
22	
23	/**
24	 * Multiply two field elements using the russian-peasant algorithm.
25	 *
26	 * @param {number} a byte
27	 * @param {number} b byte
28	 * @returns {number} byte
29	 */
30	export function gmul(a, b) {
31	  let result = 0;
32	  let x = a & 0xff;
33	  let y = b & 0xff;
34	  while (y) {
35	    if (y & 1) result ^= x;
36	    x = xtime(x);
37	    y >>= 1;
38	  }
39	  return result & 0xff;
40	}
41	
42	/**
43	 * Build the discrete log / antilog tables for the field generator 3, which is
44	 * a primitive element of GF(2^8) under the AES polynomial.
45	 *
46	 * @returns {{exp: Uint8Array, log: Uint8Array}}
47	 */
48	function buildLogTables() {
49	  const exp = new Uint8Array(256);
50	  const log = new Uint8Array(256);
51	  let x = 1;
52	  for (let i = 0; i < 255; i += 1) {
53	    exp[i] = x;
54	    log[x] = i;
55	    x = gmul(x, 3);
56	  }
57	  exp[255] = exp[0];
58	  return { exp, log };
59	}
60	
61	const { exp: EXP, log: LOG } = buildLogTables();
62	
63	/**
64	 * Multiplicative inverse in GF(2^8); zero is its own (defined) inverse.
65	 *
66	 * @param {number} a byte
67	 * @returns {number} byte
68	 */
69	export function ginv(a) {
70	  if (a === 0) return 0;
71	  return EXP[255 - LOG[a]];
72	}
73	
74	/**
75	 * Precompute a full 256-entry multiplication table for a fixed multiplier.
76	 * Used for the MixColumns / InvMixColumns coefficients.
77	 *
78	 * @param {number} multiplier byte
79	 * @returns {Uint8Array}
80	 */
81	export function multiplicationTable(multiplier) {
82	  const table = new Uint8Array(256);
83	  for (let i = 0; i < 256; i += 1) table[i] = gmul(i, multiplier);
84	  return table;
85	}
86	
87	export { EXP as GF_EXP, LOG as GF_LOG };
