1	/**
2	 * The AES substitution boxes, round constants and MixColumns tables.
3	 *
4	 * As with `gf.mjs`, every table is computed from its mathematical definition
5	 * rather than transcribed from FIPS-197.
6	 */
7	
8	import { ginv, multiplicationTable, xtime } from './gf.mjs';
9	
10	/**
11	 * Rotate a byte left by one bit.
12	 *
13	 * @param {number} b byte
14	 * @returns {number} byte
15	 */
16	function rotl8(b) {
17	  return ((b << 1) | (b >>> 7)) & 0xff;
18	}
19	
20	/**
21	 * The forward S-box: multiplicative inverse in GF(2^8) followed by the
22	 * Rijndael affine transform  s = b ^ rot1(b) ^ rot2(b) ^ rot3(b) ^ rot4(b) ^ 0x63.
23	 *
24	 * @returns {Uint8Array}
25	 */
26	function buildSbox() {
27	  const sbox = new Uint8Array(256);
28	  for (let i = 0; i < 256; i += 1) {
29	    const b = ginv(i);
30	    let s = b;
31	    let r = b;
32	    for (let k = 0; k < 4; k += 1) {
33	      r = rotl8(r);
34	      s ^= r;
35	    }
36	    sbox[i] = (s ^ 0x63) & 0xff;
37	  }
38	  return sbox;
39	}
40	
41	/**
42	 * Invert a bijective byte table.
43	 *
44	 * @param {Uint8Array} table
45	 * @returns {Uint8Array}
46	 */
47	function invertTable(table) {
48	  const inverse = new Uint8Array(256);
49	  for (let i = 0; i < 256; i += 1) inverse[table[i]] = i;
50	  return inverse;
51	}
52	
53	/**
54	 * Round constants: RCON[i] = x^(i-1) in GF(2^8). Index 0 is unused padding so
55	 * the table can be indexed directly by the key-schedule round number.
56	 *
57	 * 15 entries covers AES-128 (10 rounds) through AES-256 (14 rounds); AES-128
58	 * needs the highest index, i / Nk = 10.
59	 *
60	 * @returns {Uint8Array}
61	 */
62	function buildRcon() {
63	  const rcon = new Uint8Array(16);
64	  let value = 1;
65	  for (let i = 1; i < rcon.length; i += 1) {
66	    rcon[i] = value;
67	    value = xtime(value);
68	  }
69	  return rcon;
70	}
71	
72	export const SBOX = buildSbox();
73	export const INV_SBOX = invertTable(SBOX);
74	export const RCON = buildRcon();
75	
76	/** MixColumns coefficients. */
77	export const MUL2 = multiplicationTable(2);
78	export const MUL3 = multiplicationTable(3);
79	
80	/** InvMixColumns coefficients. */
81	export const MUL9 = multiplicationTable(9);
82	export const MUL11 = multiplicationTable(11);
83	export const MUL13 = multiplicationTable(13);
84	export const MUL14 = multiplicationTable(14);
