15	const PREFIX_CHARS = '-';
16	
17	/** argparse's `_negative_number_matcher`. */
18	const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
19	
20	/** Exit status argparse uses for command-line errors. */
21	const USAGE_ERROR_STATUS = 2;
