1	/**
2	 * Recovering the *bytes* of `argv`.
3	 *
4	 * Node decodes `process.argv` as lossy UTF-8, replacing malformed bytes with
5	 * U+FFFD, which destroys the distinction CPython preserves via
6	 * `surrogateescape`. On Linux the original bytes are still available through
7	 * `/proc/self/cmdline`, so read them from there and fall back to the decoded
8	 * strings anywhere that is unavailable.
9	 */
10	
11	import { readFileSync } from 'node:fs';
12	import { decodeSurrogateEscape } from './codecs.mjs';
13	
14	const CMDLINE = '/proc/self/cmdline';
15	
16	/**
17	 * Split a NUL-delimited blob into its records.
18	 *
19	 * @param {Buffer} blob
20	 * @returns {Buffer[]}
21	 */
22	function splitNulDelimited(blob) {
23	  const parts = [];
24	  let start = 0;
25	  for (let i = 0; i < blob.length; i += 1) {
26	    if (blob[i] === 0) {
27	      parts.push(blob.subarray(start, i));
28	      start = i + 1;
29	    }
30	  }
31	  if (start < blob.length) parts.push(blob.subarray(start));
32	  return parts;
33	}
34	
35	/**
36	 * Whether a buffer is well-formed UTF-8.
37	 *
38	 * @param {Buffer} buffer
39	 * @returns {boolean}
40	 */
41	function isValidUtf8(buffer) {
42	  try {
43	    new TextDecoder('utf-8', { fatal: true }).decode(buffer);
44	    return true;
45	  } catch {
46	    return false;
47	  }
48	}
49	
50	/**
51	 * The raw bytes of the user-supplied arguments, i.e. everything after the
52	 * interpreter and the script path.
53	 *
54	 * @returns {Uint8Array[]}
55	 */
56	export function rawArgumentBytes() {
57	  const wanted = process.argv.length - 2;
58	  const fallback = () =>
59	    process.argv.slice(2).map((argument) => new Uint8Array(Buffer.from(argument, 'utf8')));
60	
61	  if (wanted <= 0) return [];
62	
63	  try {
64	    const parts = splitNulDelimited(readFileSync(CMDLINE));
65	    if (parts.length < wanted) return fallback();
66	    const tail = parts.slice(parts.length - wanted);
67	
68	    // Guard against an unexpected cmdline layout: any argument that survived
69	    // Node's decoding intact must match what we picked up here.
70	    for (let i = 0; i < wanted; i += 1) {
71	      if (isValidUtf8(tail[i]) && tail[i].toString('utf8') !== process.argv[i + 2]) {
72	        return fallback();
73	      }
74	    }
75	    return tail.map((part) => new Uint8Array(part));
76	  } catch {
77	    return fallback();
78	  }
79	}
80	
81	/**
82	 * `sys.argv[1:]` as CPython would see it: strings that may contain
83	 * surrogate-escaped bytes.
84	 *
85	 * @returns {string[]}
86	 */
87	export function pythonArgv() {
88	  return rawArgumentBytes().map(decodeSurrogateEscape);
89	}
90	
91	/**
92	 * `os.path.basename(sys.argv[0])`, which argparse uses as the default `prog`.
93	 *
94	 * @returns {string}
95	 */
